import java.util.Scanner;
public class JTemperatureListDaysAboveThreshold {
	public static void main(String[] args) {
		//Paso 1: Leer el numero de dias de los que tenemos que ingresar los datos de temperatura.
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese la cantidad de valores de temperatura que se ingresaran:");
		int numDays = scan.nextInt();
		//Paso 2: Leer los valores de temperatura y actualizar el total acumulado
		double[] temps = new double[numDays];		
		for (int i = 0; i < numDays; i++) {
			System.out.println("Ingrese la temperatura: " );
			temps[i] = scan.nextDouble();
		}
		scan.close();
		//Paso 3: Crear un arreglo para almacenar banderas verdadero/falso que indiquen cuales dias estan por encima de 32 grados Fahrenheit
		boolean[] aboveThreshold = new boolean[numDays];
		for (int i = 0; i < temps.length; i++) {
			if ( temps[i] > 32) {
				aboveThreshold[i] = true;
			}
		}
		//Paso 4: Imprimir el resultado
		System.out.println("Dias por encima de 32 grados Fahrenheit:");
	   for (int i = 0; i < aboveThreshold.length; i++) {
		   if ( aboveThreshold[i] == true ) {
			   System.out.println("Dia " + (i + 1)); 
		   }
	   }
	}
}

